UPDATE public.boundaries b
SET polygon = sub.g,
    source = 'Deschutes County GIS Subdivisions (ST_Union of Deschutes River Recreation Homesites plats)',
    imported_at = now()
FROM (
  SELECT ST_Multi(ST_MakeValid(ST_Union(polygon))) AS g
  FROM public.boundaries
  WHERE geo_type = 'subdivision'
    AND geo_label ILIKE 'Deschutes River Recreation Homesites%'
) sub
WHERE b.geo_type = 'neighborhood'
  AND b.geo_slug = 'three-rivers'
  AND sub.g IS NOT NULL;

-- Resulting acres
SELECT geo_slug,
       ROUND((ST_Area(polygon::geography)/4046.86)::numeric,0) AS acres,
       source
FROM public.boundaries
WHERE geo_type='neighborhood'
  AND geo_slug IN ('sunriver','three-rivers','brasada-ranch','widgi-creek')
ORDER BY 1;

UPDATE public.boundaries sun
SET polygon = ST_Multi(ST_MakeValid(ST_Difference(sun.polygon, cw.polygon))),
    source = sun.source || '; minus Crosswater plat sliver',
    imported_at = now()
FROM public.boundaries cw
WHERE sun.geo_type = 'neighborhood' AND sun.geo_slug = 'sunriver'
  AND cw.geo_type = 'neighborhood' AND cw.geo_slug = 'crosswater';
